/**
 * Settles one incident against a policy, consuming the policy's remaining
 * cap. Each damage entry is matched to a distinct insured item, so a
 * repeated item type draws its own deductible.
 */
export function settleClaim(policy: Policy, damages: Damage[]): ClaimResult {
  const unclaimed = [...policy.items];

  const desired = damages.reduce((total, damage) => {
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    const [item] = unclaimed.splice(index, 1);
    return total + damagePayout(item, damage.amount);
  }, 0);

  const payout = Math.floor(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
}

